// Constants
maxDel = 2048;

// LFO for flanger effect
lfo(f) = os.lf_triangle(f) * 0.5 + 0.5;

// Delay function with feedback
delayWithFeedback(maxDelay, delayTime, feedback, input) = 
  input + feedback * (input : (+ : de.fdelay(maxDelay, delayTime)) :> _,_);

// Flanger effect
flanger(maxDelay, curDelay, depth, feedback, invert, input) = 
  input * (1 - invert) + (input : (+ : de.fdelay(maxDelay, curDelay)) ~ *(feedback)) * invert;

// Process
process = flanger(maxDel, 2.0 + 4.0 * (lfo(rate) * 0.5 + 0.5), depth, fb, 0, _),
          flanger(maxDel, 2.0 + 4.0 * (lfo(rate) * 0.5 + 0.5), depth, fb, 0, _);

