pluckGain = hslider("Pluck Gain", 0.5, 0, 1, 0.01) : si.smoo;

// Define the plucked sound effect
pluckEffect(x) = x * pluckGain * (1 - exp(-x * pluckTime));

// Define the pitch shifter
pitchShift(f, x) = x : os.osc(f);

// Define the main process
process = pitchShift(pluckFreq, pluckEffect), pitchShift(pluckFreq * 2, pluckEffect), pitchShift(pluckFreq * 3, pluckEffect);

